const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, PageOrientation
} = require('docx');
const fs = require('fs');

const INK = "24242B";
const GOLD = "B2955F";
const BODY = "3D3D45";
const SOFT = "6E6E78";
const CREAM = "FAF6EF";

const HFONT = "Georgia";
const BFONT = "Arial";

const NONE = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: NONE, bottom: NONE, left: NONE, right: NONE };

function sp(after = 60) {
  return new Paragraph({ spacing: { after }, children: [new TextRun({ text: "", size: 8 })] });
}

function rule(color = GOLD, size = 8, after = 120) {
  return new Paragraph({
    spacing: { before: 0, after },
    border: { bottom: { style: BorderStyle.SINGLE, size, color, space: 2 } },
    children: [new TextRun({ text: "", size: 4 })]
  });
}

function catHead(text) {
  return new Paragraph({
    spacing: { before: 130, after: 40 },
    children: [new TextRun({ text: text.toUpperCase(), font: BFONT, size: 15, bold: true, color: GOLD, characterSpacing: 60 })]
  });
}

function item(name, desc) {
  return new Paragraph({
    spacing: { before: 0, after: 34 },
    indent: { left: 120, hanging: 0 },
    children: [
      new TextRun({ text: name + ". ", font: BFONT, size: 16, bold: true, color: INK }),
      new TextRun({ text: desc, font: BFONT, size: 16, color: BODY })
    ]
  });
}

function col(children, width) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    borders: noBorders,
    margins: { top: 0, bottom: 0, left: 0, right: 200 },
    children
  });
}

const leftCol = [
  catHead("Revenue and Retention"),
  item("Membership Playbook", "Tier structure, pricing logic, enrollment scripts, and retention mechanics for predictable recurring revenue."),
  item("Package and Upsell Architecture", "Bundle design and upsell sequencing that raise average transaction value without discounting."),
  item("LTV Sales Playbook", "The frameworks that turn a first visit into a multi-year patient, measured and managed."),
  item("Reactivation and Referral Frameworks", "Systems that pull revenue out of the patient list you already own."),
  item("Retail as a Profit Center", "Line selection, margin targets, and retail built directly into memberships and packages."),

  catHead("Sales and Team Performance"),
  item("Conversion Playbook", "The consult-to-close system for every client-facing role, from first call to treatment plan."),
  item("Sales and Consultation Playbooks", "Scripted, trainable front desk, coordinator, provider, and esthetician conversations."),
  item("Team Kickoff Playbook", "How to launch the systems with your team so adoption happens in week one, not month three."),
  item("Compensation and Incentive Playbook", "Pay structures that reward the behavior you want without eroding margin, including how to transition existing staff."),
  item("Commission and Bonus Model", "A compliant team bonus structure with an owner guide, a team handout, and a working payout model."),
  item("Culture Index and Hiring Support", "A behavioral fit assessment used to hire the right people the first time."),

  catHead("Reputation and Market Presence"),
  item("Reputation Engine Playbook", "Systematized review generation and response so credibility shows up where patients are looking."),
  item("Celebration Event Playbook", "The in-practice event system that drives concentrated revenue and referrals in a single evening."),
  item("Strategic Partnership Frameworks", "Sourcing and structuring local partnerships that send qualified patients without ad spend."),
  item("Confidential Experience Assessment", "A secret shopper program that shows you exactly what your patients experience.")
];

const rightCol = [
  catHead("Operations and Profit"),
  item("Med Spa SOP Playbook", "Sixteen industry-standard procedures across client experience, clinical, revenue, and operations."),
  item("Ten Must-Have SOPs", "The client-facing core, from inbound inquiry through weekly KPI review, with scripts and targets."),
  item("SOP Standards and Master Index", "Numbering, ownership, review cadence, and a living register so the library never drifts."),
  item("KPI Reference Playbook and Calculator", "The numbers that matter, how to read them, and what to do when they move."),
  item("The Weekly Operating Standard", "Seventeen tracked inputs, ten calculated rates, a Monday huddle agenda, and a front desk checklist."),
  item("Weekly Scorecard System", "The companion workbook, including a sales goal calculator that works backward from your annual target."),
  item("Laser ROI Playbook", "Utilization and pricing frameworks that make expensive equipment pay for itself."),

  catHead("Execution and Accountability"),
  item("90-Day Transformation Roadmap", "The sequenced implementation plan, with owners and deadlines."),
  item("90-Day Client Action Checklist", "The working document that keeps implementation honest between calls."),
  item("Bi-Weekly Call Checklist", "The standing agenda that keeps every strategy call tied to the roadmap."),
  item("Playbook Quizzes", "Knowledge checks that confirm your team actually absorbed the training."),

  catHead("Expansion"),
  item("The Longevity Playbook", "The framework for adding a peptide-led longevity arm, including menu, three-tier membership architecture, compliance and sourcing guidance, and a 90-day launch roadmap."),

  catHead("Sales Support"),
  item("Case Study Library", "Eleven studies covering memberships, revenue leak recovery, staffing, capacity, and margin, plus individual one-pagers.")
];

const doc = new Document({
  styles: { default: { document: { run: { font: BFONT, size: 16, color: BODY } } } },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 620, right: 720, bottom: 560, left: 720 }
      }
    },
    children: [
      new Paragraph({
        spacing: { after: 40 },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: BFONT, size: 15, bold: true, color: GOLD, characterSpacing: 110 })]
      }),
      new Paragraph({
        spacing: { after: 60 },
        children: [new TextRun({ text: "The Luxora Library", font: HFONT, size: 40, bold: true, color: INK })]
      }),
      new Paragraph({
        spacing: { after: 80 },
        children: [new TextRun({
          text: "Every framework your practice owns permanently. Agencies sell traffic. We hand you the operating system that converts and keeps it. Each item below is a written, trainable framework, delivered to your team and implemented with them rather than emailed as a document.",
          font: BFONT, size: 17, color: BODY
        })]
      }),
      rule(GOLD, 10, 40),
      new Table({
        width: { size: 10800, type: WidthType.DXA },
        columnWidths: [5400, 5400],
        borders: noBorders,
        rows: [new TableRow({ children: [col(leftCol, 5400), col(rightCol, 5400)] })]
      }),
      sp(100),
      rule(GOLD, 10, 100),
      new Table({
        width: { size: 10800, type: WidthType.DXA },
        columnWidths: [10800],
        borders: noBorders,
        rows: [new TableRow({
          children: [new TableCell({
            width: { size: 10800, type: WidthType.DXA },
            borders: noBorders,
            shading: { fill: CREAM, type: ShadingType.CLEAR },
            margins: { top: 140, bottom: 140, left: 200, right: 200 },
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                spacing: { after: 30 },
                children: [new TextRun({ text: "Every library above begins with the same first step.", font: HFONT, size: 20, bold: true, color: INK })]
              }),
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: "Book your Revenue Leak Audit at theluxoracollective.co", font: BFONT, size: 16, color: SOFT })]
              })
            ]
          })]
        })]
      })
    ]
  }]
});

Packer.toBuffer(doc).then(b => {
  fs.writeFileSync("/home/claude/Luxora_Library_One_Pager.docx", b);
  console.log("built");
});

