const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType
} = require('docx');
const fs = require('fs');

const INK = "24242B";
const GOLD = "B2955F";
const BODY = "3D3D45";
const SOFT = "6E6E78";
const CREAM = "FAF6EF";

const HFONT = "Georgia";
const BFONT = "Arial";

const NONE = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: NONE, bottom: NONE, left: NONE, right: NONE };

function rule(size = 10, after = 120) {
  return new Paragraph({
    spacing: { before: 0, after },
    border: { bottom: { style: BorderStyle.SINGLE, size, color: GOLD, space: 2 } },
    children: [new TextRun({ text: "", size: 4 })]
  });
}

function eyebrow(text, before = 200) {
  return new Paragraph({
    spacing: { before, after: 50 },
    children: [new TextRun({ text: text.toUpperCase(), font: BFONT, size: 15, bold: true, color: GOLD, characterSpacing: 90 })]
  });
}

function h2(text, before = 0) {
  return new Paragraph({
    spacing: { before, after: 60 },
    children: [new TextRun({ text, font: HFONT, size: 24, bold: true, color: INK })]
  });
}

function p(text, opts = {}) {
  return new Paragraph({
    spacing: { after: opts.after === undefined ? 80 : opts.after },
    children: [new TextRun({
      text,
      font: BFONT,
      size: opts.size || 17,
      color: opts.color || BODY,
      italics: opts.italics || false,
      bold: opts.bold || false
    })]
  });
}

function attrib(text) {
  return new Paragraph({
    spacing: { after: 60 },
    children: [new TextRun({ text: text, font: BFONT, size: 16, bold: true, color: INK })]
  });
}

function quoteBox(text, name) {
  return new Table({
    width: { size: 10800, type: WidthType.DXA },
    columnWidths: [10800],
    borders: noBorders,
    rows: [new TableRow({
      children: [new TableCell({
        width: { size: 10800, type: WidthType.DXA },
        borders: { top: NONE, bottom: NONE, right: NONE, left: { style: BorderStyle.SINGLE, size: 18, color: GOLD, space: 8 } },
        shading: { fill: CREAM, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 200, right: 200 },
        children: [
          new Paragraph({
            spacing: { after: 50 },
            children: [new TextRun({ text: text, font: BFONT, size: 17, italics: true, color: BODY })]
          }),
          new Paragraph({
            children: [new TextRun({ text: name, font: BFONT, size: 16, bold: true, color: INK })]
          })
        ]
      })]
    })]
  });
}

// Two-up testimonial cell
function tCell(headline, body, name, width) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    borders: noBorders,
    margins: { top: 0, bottom: 0, left: 0, right: 220 },
    children: [
      new Paragraph({
        spacing: { after: 50 },
        children: [new TextRun({ text: headline, font: HFONT, size: 19, bold: true, color: INK })]
      }),
      new Paragraph({
        spacing: { after: 50 },
        children: [new TextRun({ text: body, font: BFONT, size: 16, italics: true, color: BODY })]
      }),
      new Paragraph({
        spacing: { after: 200 },
        children: [new TextRun({ text: name, font: BFONT, size: 15, bold: true, color: GOLD })]
      })
    ]
  });
}

function twoUp(a, b) {
  return new Table({
    width: { size: 10800, type: WidthType.DXA },
    columnWidths: [5400, 5400],
    borders: noBorders,
    rows: [new TableRow({ children: [a, b] })]
  });
}

const doc = new Document({
  styles: { default: { document: { run: { font: BFONT, size: 17, color: BODY } } } },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 680, right: 720, bottom: 600, left: 720 }
      }
    },
    children: [
      new Paragraph({
        spacing: { after: 40 },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: BFONT, size: 15, bold: true, color: GOLD, characterSpacing: 110 })]
      }),
      new Paragraph({
        spacing: { after: 50 },
        children: [new TextRun({ text: "Real Med Spas. Real Results.", font: HFONT, size: 38, bold: true, color: INK })]
      }),
      p("What happens when you fix the foundation first and build a system that actually works.", { size: 18, color: SOFT, after: 100 }),
      rule(10, 60),

      // CASE STUDY 1
      eyebrow("Case Study One", 160),
      h2("From $37K per month to $55K in thirty days"),
      p("Mike's med spa was stuck at $37,000 per month with inconsistent leads, climbing no-shows, and a front desk buried in administrative work. The problem was never traffic. It was everything that happened after the lead arrived."),
      p("We automated lead qualification so the team spent its time on serious buyers, refined the messaging, and tightened the consultation flow. Within one month, consultation conversion moved from 34 percent to 62 percent and revenue reached $55,000 in thirty days. No additional staff. No promotional discounting."),
      quoteBox("This wasn't some cookie-cutter marketing agency. Bethany brought real strategy plus trusted growth partners. If you're a med spa owner looking to grow without getting buried in busy work or flaky leads, talk to Bethany.", "Mike, Med Spa Owner"),

      // CASE STUDY 2
      eyebrow("Case Study Two", 200),
      h2("Finding the leak in an underperforming location"),
      p("Lisa owns multiple med spas. One location had been struggling for months and she could not pinpoint why. We conducted a Confidential Experience Assessment, moving through her funnel as a real client from booking through checkout, then delivered a written report and a working session."),
      p("Some findings confirmed what she had been putting off. Others she had never considered, including one change as simple as giving every new client a personalized tour of the team, the devices, and the space. Every recommendation arrived with step-by-step guidance on how to implement it."),
      quoteBox("Bethany is incredibly personable and spends time on your spa specifically. She makes sure her feedback is actionable with step-by-step guidance. I highly recommend her if you're looking to grow your med spa or understand opportunities to improve.", "Lisa Bell, Multi-Location Med Spa Owner"),

      // PAGE TWO
      eyebrow("In Their Own Words", 300),
      new Paragraph({
        spacing: { after: 70 },
        children: [new TextRun({ text: "What med spa owners are saying", font: HFONT, size: 30, bold: true, color: INK })]
      }),
      rule(10, 140),

      twoUp(
        tCell(
          "They completely transformed the way my med spa operates.",
          "\u201CThey built our entire Acquisition System and it finally feels like we have a real growth engine instead of guessing on marketing. Our leads are nurtured instantly, our calendar stays full, and I always know exactly where our revenue is coming from. They did not just fix our marketing, they helped my entire sales and operations work more efficiently. My ad spend now pays for itself and the rest has become pure profit.\u201D",
          "Megan L., Scottsdale, AZ",
          5400
        ),
        tCell(
          "TLC finally gave me a system that works.",
          "\u201CThey built everything for us including CRM, follow up, ads, retention planning, and sales support. I love how simple they make the process and how much clarity they bring to the numbers. What I appreciate most is the continued guidance even after the program ended. They still check in, help adjust the strategy, and make sure our results stay strong. They delivered way more than what was promised.\u201D",
          "Danielle P., Nashville, TN",
          5400
        )
      ),

      twoUp(
        tCell(
          "The business finally runs smoothly without me chasing every little thing.",
          "\u201CThe follow up, booking, content direction, ads, and retention planning all work together like one big profitable system. The team makes the marketing side feel easy to understand, unlike most agencies who do not even check in or explain anything. Our revenue is more consistent than it has ever been.\u201D",
          "Christopher K., Austin, TX",
          5400
        ),
        tCell(
          "The secret shopper experience was eye-opening in the best way.",
          "\u201CBethany came into our spa as a real client and experienced everything from booking to checkout, then delivered a detailed report that showed us exactly where we were losing trust, conversions, and revenue. The insights were so valuable that we immediately signed up for ongoing monthly support. Our booking rate and client retention have improved dramatically.\u201D",
          "Olivia S., Denver, CO",
          5400
        )
      ),

      twoUp(
        tCell(
          "Working one-on-one with Bethany changed the trajectory of my practice.",
          "\u201CThe custom consulting was tailored to my goals, my community, and the kind of business I wanted to build. We refined my offers, improved my systems, trained my team, and positioned the practice as a trusted pillar in our local market.\u201D",
          "Emily R., Franklin, TN",
          5400
        ),
        tCell(
          "The systems helped us shift from one-time visits to long-term clients.",
          "\u201CThe systems and support she put in place helped us shift from one-time visits to long-term clients. We have seen a huge increase in lifetime value and more consistency month over month. I would absolutely recommend her to any practice looking for real results.\u201D",
          "Hannah M., San Diego, CA",
          5400
        )
      ),

      rule(10, 120),
      new Table({
        width: { size: 10800, type: WidthType.DXA },
        columnWidths: [10800],
        borders: noBorders,
        rows: [new TableRow({
          children: [new TableCell({
            width: { size: 10800, type: WidthType.DXA },
            borders: noBorders,
            shading: { fill: CREAM, type: ShadingType.CLEAR },
            margins: { top: 160, bottom: 160, left: 200, right: 200 },
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                spacing: { after: 40 },
                children: [new TextRun({ text: "Ready to see results like this in your own med spa?", font: HFONT, size: 22, bold: true, color: INK })]
              }),
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: "Book your Growth Assessment Call at theluxoracollective.co", font: BFONT, size: 17, color: SOFT })]
              })
            ]
          })]
        })]
      }),
      new Paragraph({
        spacing: { before: 160 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Results vary. No specific revenue outcomes are guaranteed. Success depends on client commitment to implementation.", font: BFONT, size: 13, color: SOFT })]
      })
    ]
  }]
});

Packer.toBuffer(doc).then(b => {
