{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat
} = require('docx');
const fs = require('fs');

const INK = "24242B";
const GOLD = "B2955F";
const BODY = "3D3D45";
const SOFT = "6E6E78";
const CREAM = "FAF6EF";
const LINE = "DCD5C8";

const HFONT = "Georgia";
const BFONT = "Arial";

const NONE = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: NONE, bottom: NONE, left: NONE, right: NONE };

function rule(size = 10, after = 120, color = GOLD) {
  return new Paragraph({
    spacing: { before: 0, after },
    border: { bottom: { style: BorderStyle.SINGLE, size, color, space: 2 } },
    children: [new TextRun({ text: "", size: 4 })]
  });
}

function eyebrow(text, before = 200) {
  return new Paragraph({
    spacing: { before, after: 50 },
    children: [new TextRun({ text: text.toUpperCase(), font: BFONT, size: 15, bold: true, color: GOLD, characterSpacing: 90 })]
  });
}

function h1(text, before = 0, size = 30) {
  return new Paragraph({
    spacing: { before, after: 70 },
    children: [new TextRun({ text, font: HFONT, size, bold: true, color: INK })]
  });
}

function h2(text, before = 0) {
  return new Paragraph({
    spacing: { before, after: 60 },
    children: [new TextRun({ text, font: HFONT, size: 23, bold: true, color: INK })]
  });
}

function label(text, before = 130) {
  return new Paragraph({
    spacing: { before, after: 45 },
    children: [new TextRun({ text: text.toUpperCase(), font: BFONT, size: 14, bold: true, color: SOFT, characterSpacing: 50 })]
  });
}

function p(text, opts = {}) {
  return new Paragraph({
    spacing: { after: opts.after === undefined ? 80 : opts.after },
    children: [new TextRun({
      text, font: BFONT,
      size: opts.size || 17,
      color: opts.color || BODY,
      italics: !!opts.italics,
      bold: !!opts.bold
    })]
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "lux-bullets", level: 0 },
    spacing: { after: 30 },
    children: [new TextRun({ text, font: BFONT, size: 16, color: BODY })]
  });
}

function client(text) {
  return new Paragraph({
    spacing: { before: 90, after: 60 },
    children: [new TextRun({ text: "Client: " + text, font: BFONT, size: 15, bold: true, color: GOLD })]
  });
}

function cellText(text, opts = {}) {
  return new Paragraph({
    alignment: opts.align || AlignmentType.LEFT,
    children: [new TextRun({
      text, font: BFONT,
      size: opts.size || 15,
      bold: !!opts.bold,
      color: opts.color || BODY
    })]
  });
}

function td(text, width, opts = {}) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    shading: { fill: opts.fill || "FFFFFF", type: ShadingType.CLEAR },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 2, color: LINE },
      bottom: { style: BorderStyle.SINGLE, size: 2, color: LINE },
      left: NONE, right: NONE
    },
    margins: { top: 70, bottom: 70, left: 140, right: 140 },
    children: [cellText(text, opts)]
  });
}

// Three-column before/after results table
function resultsTable(rows) {
  const W = [4400, 3200, 3200];
  const head = new TableRow({
    tableHeader: true,
    children: ["Metric", "Before", "After"].map((h, i) =>
      td(h, W[i], { bold: true, color: INK, fill: CREAM, size: 14 }))
  });
  const body = rows.map(r => new TableRow({
    children: [
      td(r[0], W[0], { bold: true, color: INK }),
      td(r[1], W[1], { color: SOFT }),
      td(r[2], W[2], { bold: true, color: INK })
    ]
  }));
  return new Table({
    width: { size: 10800, type: WidthType.DXA },
    columnWidths: W,
    rows: [head, ...body]
  });
}

// Two-column leak table
function leakTable(rows, total) {
  const W = [7400, 3400];
  const head = new TableRow({
    tableHeader: true,
    children: [
      td("Revenue Leak", W[0], { bold: true, color: INK, fill: CREAM, size: 14 }),
      td("Estimated Annual Impact", W[1], { bold: true, color: INK, fill: CREAM, size: 14, align: AlignmentType.RIGHT })
    ]
  });
  const body = rows.map(r => new TableRow({
    children: [
      td(r[0], W[0], { color: BODY }),
      td(r[1], W[1], { bold: true, color: INK, align: AlignmentType.RIGHT })
    ]
  }));
  const foot = new TableRow({
    children: [
      td("Total Identified Opportunity", W[0], { bold: true, color: INK, fill: CREAM }),
      td(total, W[1], { bold: true, color: INK, fill: CREAM, align: AlignmentType.RIGHT })
    ]
  });
  return new Table({
    width: { size: 10800, type: WidthType.DXA },
    columnWidths: W,
    rows: [head, ...body, foot]
  });
}

function quoteBox(text, name) {
  return new Table({
    width: { size: 10800, type: WidthType.DXA },
    columnWidths: [10800],
    borders: noBorders,
    rows: [new TableRow({
      children: [new TableCell({
        width: { size: 10800, type: WidthType.DXA },
        borders: { top: NONE, bottom: NONE, right: NONE, left: { style: BorderStyle.SINGLE, size: 18, color: GOLD, space: 8 } },
        shading: { fill: CREAM, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 200, right: 200 },
        children: [
          new Paragraph({
            spacing: { after: 50 },
            children: [new TextRun({ text: text, font: BFONT, size: 17, italics: true, color: BODY })]
          }),
          new Paragraph({
            children: [new TextRun({ text: name, font: BFONT, size: 16, bold: true, color: INK })]
          })
        ]
      })]
    })]
  });
}

function tCell(headline, body, name, width) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    borders: noBorders,
    margins: { top: 0, bottom: 0, left: 0, right: 220 },
    children: [
      new Paragraph({ spacing: { after: 50 }, children: [new TextRun({ text: headline, font: HFONT, size: 19, bold: true, color: INK })] }),
      new Paragraph({ spacing: { after: 50 }, children: [new TextRun({ text: body, font: BFONT, size: 16, italics: true, color: BODY })] }),
      new Paragraph({ spacing: { after: 200 }, children: [new TextRun({ text: name, font: BFONT, size: 15, bold: true, color: GOLD })] })
    ]
  });
}

function twoUp(a, b) {
  return new Table({
    width: { size: 10800, type: WidthType.DXA },
    columnWidths: [5400, 5400],
    borders: noBorders,
    rows: [new TableRow({ children: [a, b] })]
