function renderStudy(s) {
  const out = [];
  out.push(eyebrow("Case Study " + String(s.n).padStart(2, "0"), 320));
  out.push(h2(s.title));
  out.push(p("Practice Type: " + s.type, { size: 15, color: SOFT, italics: true, after: 60 }));
  out.push(rule(6, 130, LINE));

  out.push(label("The Challenge", 0));
  if (s.challengeIntro) out.push(p(s.challengeIntro, { after: 70 }));
  s.challenge.forEach(b => out.push(bullet(b)));

  if (s.leaks) {
    out.push(label("What We Found"));
    out.push(leakTable(s.leaks, s.leakTotal));
  }

  if (s.implemented) {
    out.push(label("What We Implemented"));
    if (s.implementedIntro) out.push(p(s.implementedIntro, { after: 70 }));
    s.implemented.forEach(b => out.push(bullet(b)));
  }

  if (s.results) {
    out.push(label(s.resultsLabel || "Results"));
    out.push(resultsTable(s.results));
  }

  out.push(label(s.impactLabel || "Financial Impact"));
  out.push(p(s.impact, { after: 60 }));

  if (s.quote) {
    out.push(new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: "", size: 6 })] }));
    out.push(quoteBox(s.quote, s.client));
  } else {
    out.push(client(s.client));
  }
  return out;
}

